    Page(maxWidth=700.dp){Heading("Dress by the Weather Pro","Good style.\nLess guesswork.");EditorialPhoto("couple_dry_5_2_3",260.dp);EditorialText("One purchase. Your own style studio.",29)
        ProFeatureRow(Icons.Outlined.CalendarMonth,"Dress the week","Save occasions and outfit variations for the next seven forecast days.")
        ProFeatureRow(Icons.Outlined.Checkroom,"Wear what you own","Build a private wardrobe with optional photos, comfort ranges and weather-ready pieces.")
        ProFeatureRow(Icons.Outlined.Luggage,"Pack a better capsule","Plan daily outfits and reuse your pieces across changing destination weather.")
        ProFeatureRow(Icons.Outlined.MenuBook,"Explore the full collection","Browse 214 reviewed couple photographs and eight original styling guides.")
        Action(m.pro.price?.let{"Unlock Pro · $it"}?:if(m.pro.loading)"Loading Google Play price…"else"Price unavailable",Modifier.fillMaxWidth(),enabled=m.pro.product!=null&&!m.pro.purchasing,primary=true){context.activity()?.let{m.pro.purchase(it)}}
        Caption("One-time purchase. Permanent unlock for this app. No subscription or recurring charge. Your Google Account handles payment and restoration.");m.pro.message?.let{Caption(it)}
        Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){TextButton({m.pro.refresh(true)},enabled=!m.pro.purchasing){Text("Restore Purchases",color=Ink)};TextButton({m.pro.connect()},enabled=!m.pro.loading){Text("Reload price",color=Ink)}}
        Caption("Always free: global weather, current location, worldwide search, daily outfit advice and basic packing lists.",color=Olive)
        Action("Preview the sample Studio",Modifier.fillMaxWidth(),icon=Icons.Outlined.Visibility){m.startStudioDemo()}
        Caption("Explore every Studio tool with sample weather. Preview changes are temporary and separate from your own data. No purchase or sign-in required.")
        Row(horizontalArrangement=Arrangement.spacedBy(18.dp)){TextButton({uri.openUri("https://www.oanarinaldi.com/dressbytheweatherandroidprivacy.html")}){Text("Privacy",color=Ink)};TextButton({uri.openUri("https://play.google.com/about/play-terms/")}){Text("Terms",color=Ink)}}
    }
}
