@Composable fun WeeklyScreen(m:DressModel,n:Navigator){Page(maxWidth=760.dp){Heading("${m.p.city.name} · Your next seven forecast days","A week,\nwell dressed.");if(m.forecast?.sample==true)SampleLabel();Body("Give each day an occasion. Your outfit follows its forecast; your choices stay saved for this city.");if(m.days.isEmpty())EmptyForecast(m);m.days.take(7).forEach{day->val plan=m.planned(day.date);val style=plan?.style?:m.p.style;val variant=plan?.variant?:0;val o=m.outfit(day.representative.conditions,style)
