    }}}
@Composable fun GarmentThumb(m:DressModel,g:Garment){Box(Modifier.size(62.dp,78.dp).clip(RoundedCornerShape(13.dp)).background(Sand.copy(alpha=.3f)),contentAlignment=Alignment.Center){if(g.photo!=null)AsyncImage(m.photoFile(g.photo),"Your saved wardrobe photo",Modifier.fillMaxSize(),contentScale=androidx.compose.ui.layout.ContentScale.Fit)else Icon(Icons.Outlined.Checkroom,null,Modifier.size(30.dp),tint=Olive)}}
@Composable fun WardrobeScreen(m:DressModel,n:Navigator){Page{Heading("The clothes you already love","Your own\nwardrobe.");Body("A private collection on this device. Add pieces, choose their comfortable temperatures and mark what’s ready to wear.");Action("Add a piece",Modifier.fillMaxWidth(),icon=Icons.Outlined.Add){n.open("garment")};SectionLabel("Your pieces · ${m.p.wardrobe.size}");if(m.p.wardrobe.isEmpty())Body("Start with a coat, a favorite shirt and your most comfortable shoes.");m.p.wardrobe.forEach{g->Box(Modifier.clickable{n.open("garment",g.id)}){FormCard{Row(verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(15.dp)){GarmentThumb(m,g);Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(6.dp)){EditorialText(g.name,24);Caption(listOf(g.category.label,g.color).filter{it.isNotEmpty()}.joinToString(" · "));Caption(if(g.available)"Ready to wear"else"In the laundry",color=if(g.available)Olive else Muted)};Icon(Icons.Outlined.ChevronRight,null,Modifier.size(17.dp),tint=Ink)}}}}
