    }}
@Composable fun GarmentScreen(m:DressModel,n:Navigator,id:String){val existing=m.p.wardrobe.firstOrNull{it.id==id};var g by remember{mutableStateOf(existing?:Garment())};var photo by remember{mutableStateOf<Uri?>(null)};var busy by remember{mutableStateOf(false)};var error by remember{mutableStateOf<String?>(null)};var deletion by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();val picker=rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()){photo=it}
    Page{SectionLabel("Your piece");FormCard{OutlinedTextField(g.name,{g=g.copy(name=it)},Modifier.fillMaxWidth(),placeholder={Text("Name, e.g. cream linen shirt")},singleLine=true);Choice("Category",Category.entries.map{it.label},g.category.label){name->g=g.copy(category=Category.entries.first{it.label==name})};OutlinedTextField(g.color,{g=g.copy(color=it)},Modifier.fillMaxWidth(),placeholder={Text("Color or pattern")},singleLine=true);Action("Choose an optional photo",Modifier.fillMaxWidth(),icon=Icons.Outlined.PhotoLibrary){picker.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))};if(photo!=null)AsyncImage(photo,"Selected wardrobe photo",Modifier.fillMaxWidth().height(200.dp),contentScale=androidx.compose.ui.layout.ContentScale.Fit)else if(g.photo!=null)GarmentThumb(m,g)}
        SectionLabel("When you wear it");FormCard{Text("Comfortable from ${m.temperature(g.minimum)}",color=Ink);Slider(g.minimum.toFloat(),{v->g=g.copy(minimum=v.toDouble(),maximum=maxOf(g.maximum,v.toDouble()))},valueRange=-25f..45f,steps=69);Text("Comfortable up to ${m.temperature(g.maximum)}",color=Ink);Slider(g.maximum.toFloat(),{v->g=g.copy(maximum=v.toDouble(),minimum=minOf(g.minimum,v.toDouble()))},valueRange=-25f..45f,steps=69);SwitchRow("Suitable for rain or snow",g.waterResistant){g=g.copy(waterResistant=it)};SwitchRow("Ready to wear",g.available){g=g.copy(available=it)}};Caption("Choose your own estimated feels-like comfort range. Mark outerwear and shoes as rain-ready only when they suit wet conditions.");SectionLabel("Occasions");FormCard{Occasion.entries.forEach{s->SwitchRow(s.label,s in g.occasions){on->g=g.copy(occasions=if(on)g.occasions+s else g.occasions-s)}}};error?.let{Caption(it,color=Color.Red)};Action(if(busy)"Saving…"else"Save piece",Modifier.fillMaxWidth(),enabled=g.name.isNotBlank()&&g.occasions.isNotEmpty()&&!busy,primary=true){busy=true;scope.launch{try{m.saveGarment(g,photo);n.back()}catch(e:Exception){error=e.message?:"The piece couldn’t be saved. Please try again."}finally{busy=false}}};if(existing!=null)TextButton({deletion=true}){Text("Delete this piece",color=Color(0xFFAD3838))};Caption("Photos are saved only in this app on your device. They aren’t uploaded for AI analysis.")
    }
    if(deletion)AlertDialog(onDismissRequest={deletion=false},title={Text("Delete this piece and its saved photo?")},confirmButton={TextButton({m.removeGarment(g);n.back()}){Text("Delete piece")}},dismissButton={TextButton({deletion=false}){Text("Cancel")}})
}
@Composable fun LibraryScreen(m:DressModel,n:Navigator){var collection by rememberSaveable{mutableStateOf("The style guides")};var weather by rememberSaveable{mutableStateOf("All")};var occasion by rememberSaveable{mutableStateOf("All")};var temperature by rememberSaveable{mutableIntStateOf(-1)};var favorites by rememberSaveable{mutableStateOf(false)}
    Page(maxWidth=850.dp){Heading("The Pro editorial collection","Good looks.\nEvery forecast.");Segmented(listOf("The style guides","All photographs"),collection,{collection=it});if(collection=="The style guides")m.guides.forEach{guide->Column(Modifier.clickable{n.open("guide",guide.id)},verticalArrangement=Arrangement.spacedBy(13.dp)){m.editorial.firstOrNull{it.collection==guide.collections.first()}?.let{EditorialPhoto(it.id,230.dp)};Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(6.dp)){EditorialText(guide.title,29);Caption(guide.subtitle)};Icon(Icons.Outlined.NorthEast,null,tint=Ink)}}}else{
        FormCard{Choice("Weather",listOf("All","Dry","Rain","Snow"),weather){weather=it};Choice("Occasion",listOf("All")+Occasion.entries.map{it.label},occasion){occasion=it};Choice("Temperature",listOf("All temperature ranges")+ranges,if(temperature<0)"All temperature ranges"else ranges[temperature]){temperature=ranges.indexOf(it)};SwitchRow("Only my saved photographs",favorites){favorites=it}}
        val entries=m.editorial.filter{(weather=="All"||it.weather==weather.lowercase())&&(occasion=="All"||it.occasion==occasion)&&(temperature<0||it.band==temperature)&&(!favorites||it.id in m.p.favorites)}
        Caption("${entries.size} editorial photographs · inspiration, not a live forecast")
        entries.chunked(2).forEach{row->Row(horizontalArrangement=Arrangement.spacedBy(14.dp)){row.forEach{e->Column(Modifier.weight(1f).clickable{n.open("editorial",e.id)},verticalArrangement=Arrangement.spacedBy(9.dp)){EditorialPhoto(e.id,full=true);Text(e.occasion,color=Ink,fontSize=12.sp,fontWeight=FontWeight.SemiBold);Caption(e.range)}};if(row.size==1)Spacer(Modifier.weight(1f))}}
        if(entries.isEmpty())GlassCard{EditorialText("A little room for inspiration",27);Body("Try different filters, or save photographs from the collection.")}
    }}
}
