@Composable fun EditorialScreen(m:DressModel,n:Navigator,id:String){val e=m.editorial.firstOrNull{it.id==id}?:return;Page{EditorialPhoto(e.id,full=true);Heading("Editorial inspiration · ${e.weather}","${e.occasion},\nconsidered.");Body("${e.range}. A fictional couple, a considered palette and a starting point for your own wardrobe. This photograph is editorial inspiration; follow your actual forecast and clothing checklist when choosing layers.");Action(if(e.id in m.p.favorites)"Saved to your collection"else"Save this inspiration",Modifier.fillMaxWidth(),icon=Icons.Outlined.BookmarkBorder){m.favorite(e.id)};m.current?.let{w->Action("Adapt this occasion to my weather",Modifier.fillMaxWidth(),primary=true){n.open(Destination("outfit",weather=w,style=Occasion.valueOf(e.occasion)))}}}}
